import { BridgeError, requireData, type BridgeFetch } from './bridge-protocol';
/** Complete authorized list, with a hard failure rather than a misleading truncated result. */
export async function fetchScopedPages<T extends {id:string;babyId:string}>(fetchApi:BridgeFetch,token:string,endpoint:string,babyId:string):Promise<T[]> {
  const records:T[]=[],ids=new Set<string>(),cursors=new Set<string>();let cursor:string|null=null;
  for(let count=0;count<200;count++) {
    const query=new URLSearchParams({limit:'100'});if(cursor)query.set('cursor',cursor);
    const response=await fetchApi<T[]>(`${endpoint}?${query}`,{accessToken:token});const data=requireData(response);
    if(!Array.isArray(data)||data.length>100||!response.page||!(response.page.nextCursor===null||typeof response.page.nextCursor==='string'))throw new BridgeError(502,'UPSTREAM_INVALID_PAGE','上游分页数据不完整');
    for(const record of data) {
      if(!record||record.babyId!==babyId||typeof record.id!=='string'||ids.has(record.id))throw new BridgeError(502,'UPSTREAM_SCOPE_MISMATCH','记录归属或分页标识不一致');
      ids.add(record.id);records.push(record);
    }
    cursor=response.page.nextCursor;if(cursor===null)return records;
    if(!cursor||cursors.has(cursor))throw new BridgeError(502,'UPSTREAM_CURSOR_LOOP','上游分页游标重复');cursors.add(cursor);
  }
  throw new BridgeError(503,'HISTORY_SCAN_LIMIT','数据超过完整读取上限，未返回截断结果');
}

import { randomUUID } from "node:crypto";
import { growdeskRouteBoundary } from "./route-boundary";
import { BridgeError,pathId,requireData } from "./bridge-protocol";
import { resolveBffSession } from "./session";
import { growdeskFetch } from "./client";
import { readJsonObject } from "./record-route-helpers";
import { checkRateLimit } from "@/lib/rate-limit";
export function durableParseRecord(request:Request){
  return growdeskRouteBoundary(request,async()=>{
    const session=await resolveBffSession(request);if(!session)throw new BridgeError(401,"UNAUTHORIZED","请先登录");
    if(!checkRateLimit(`parse_record:${session.user.id}`,20,60000).success)throw new BridgeError(429,"RATE_LIMITED","整理请求过于频繁");
    const body=await readJsonObject(request);const text=typeof body.text==="string"?body.text.trim():"";
    if(!text||text.length>2000)throw new BridgeError(400,"INVALID_MESSAGE","请输入 1–2000 字符");
    const babyId=pathId(body.babyId),clientMessageId=typeof body.clientMessageId==="string"?body.clientMessageId:randomUUID();
    const contextType=typeof body.contextType==="string"?body.contextType:"general";
    const conversation=requireData(await growdeskFetch<{id:string}>("/api/v1/web/ai/sessions",{method:"POST",accessToken:session.accessToken,body:{babyId,contextType,title:text.slice(0,24),clientRequestId:clientMessageId}}));
    const run=requireData(await growdeskFetch<{id:string}>(`/api/v1/ai/sessions/${pathId(conversation.id)}/runs`,{method:"POST",accessToken:session.accessToken,body:{clientMessageId,message:"请把以下口述整理为待人工确认的记录；不确定的时间或必要字段先询问，不要假装已保存。\n"+text}}));
    return Response.json({sessionId:conversation.id,runId:run.id,transcript:text},{status:202});
  });
}

import {createHash} from 'node:crypto';
import {growdeskFetch} from './client';
import {BridgeError,requireData,pathId} from './bridge-protocol';
import {loadWebBaby} from './bridge-identity';
/** Upload only bytes supplied by this authenticated request; never fetch client image URLs. */
export async function uploadPrivateBytes(token:string,babyId:string,bytes:Uint8Array,mimeType:string,purpose:'medical_report'|'voice_note'){
  const baby=await loadWebBaby(growdeskFetch,token,babyId);if(!baby)throw new BridgeError(404,'BABY_NOT_FOUND','请先选择宝宝');
  const sha256=createHash('sha256').update(bytes).digest('hex');
  const item=requireData(await growdeskFetch<{id:string;uploadUrl:string}>('/api/v1/attachments',{method:'POST',accessToken:token,body:{purpose,mimeType,byteSize:bytes.byteLength,sha256,ownerScope:{familyId:baby.familyId,babyId}}}));
  const url=new URL(item.uploadUrl);if(!['http:','https:'].includes(url.protocol)||url.username||url.password)throw new BridgeError(502,'INVALID_UPLOAD_URL','后端返回了无效上传地址');
  const response=await fetch(url,{method:'PUT',body:new Uint8Array(bytes),headers:{'content-type':mimeType},redirect:'error',signal:AbortSignal.timeout(30000)});if(!response.ok)throw new BridgeError(502,'UPLOAD_FAILED','附件上传失败');
  requireData(await growdeskFetch(`/api/v1/attachments/${pathId(item.id)}/complete`,{method:'POST',accessToken:token,body:{byteSize:bytes.byteLength,sha256}}));return item.id;
}

import { GROWDESK_CONFIG } from "@/lib/config";
import { verifyBffCsrf } from "./csrf";
import { bridgeErrorResponse } from "./bridge-protocol";

/** Preserve transport/auth errors and disable caching of authenticated BFF data. */
export async function growdeskRouteBoundary(request: Request, run: () => Promise<Response>): Promise<Response> {
  if (!GROWDESK_CONFIG.enabled) return run();
  try {
    const denied = verifyBffCsrf(request);
    const response = denied ?? await run();
    response.headers.set("cache-control", "no-store");
    return response;
  } catch (error) {
    return bridgeErrorResponse(error);
  }
}

import {randomUUID} from 'node:crypto';
import {growdeskRouteBoundary} from './route-boundary';
import {resolveBffSession} from './session';
import {BridgeError,pathId} from './bridge-protocol';
import {uploadPrivateBytes} from './private-upload';
import {bffAiJobStore} from './ai-jobs';
import {checkRateLimit} from '@/lib/rate-limit';
export function transcribeThroughBackend(request:Request){return growdeskRouteBoundary(request,async()=>{
  const session=await resolveBffSession(request);if(!session)throw new BridgeError(401,'UNAUTHORIZED','请重新登录');
  if(!checkRateLimit(`transcribe:${session.user.id}`,20,60000).success)throw new BridgeError(429,'RATE_LIMITED','请求过于频繁');
  const form=await request.formData();const audio=form.get('audio');const babyId=pathId(form.get('babyId'));if(!(audio instanceof File)||!audio.size||audio.size>25000000)throw new BridgeError(400,'INVALID_AUDIO','录音为空或超过 25MB');
  const mime=audio.type.split(';')[0]!.trim();if(!['audio/webm','audio/ogg','audio/mp4','audio/mpeg','audio/wav','audio/x-wav'].includes(mime))throw new BridgeError(400,'INVALID_AUDIO','录音格式不支持');
  const id=await uploadPrivateBytes(session.accessToken,babyId,new Uint8Array(await audio.arrayBuffer()),mime,'voice_note');
  const job=await bffAiJobStore.createJob({userId:session.user.id,babyId,type:'voice_transcription',attachmentId:id,clientRequestId:String(form.get('clientRequestId')||randomUUID()),accessToken:session.accessToken});
  return Response.json({jobId:job.id,babyId,status:'processing'},{status:202,headers:{'cache-control':'no-store'}});
});}

import {randomUUID} from "node:crypto";
import {growdeskRouteBoundary} from "./route-boundary";
import {BridgeError,pathId,requireData} from "./bridge-protocol";
import {resolveBffSession} from "./session";
import {growdeskFetch} from "./client";
import {loadWebBaby} from "./bridge-identity";
import {tryVoiceFastPath} from "@/lib/agent/voice-fast-path";
import {bffVoiceLogStore} from "./voice-logs";
import {checkRateLimit} from "@/lib/rate-limit";
import type {DurableChatRun} from "./durable-chat";

export function durableVoiceRequest(request:Request):Promise<Response>{
  return growdeskRouteBoundary(request,async()=>{
    const session=await resolveBffSession(request);
    if(!session)throw new BridgeError(401,"UNAUTHORIZED","请先登录");
    if(!checkRateLimit(`voice:${session.user.id}`,30,60000).success)throw new BridgeError(429,"RATE_LIMITED","语音请求过于频繁");
    let body:Record<string,unknown>;
    try {const raw=await request.json();body=typeof raw==="string"?{text:raw}:raw;
      if(!body||Array.isArray(body)||typeof body!=="object")throw new Error();
    }catch{throw new BridgeError(400,"INVALID_JSON","请求正文无效");}
    const rawText=[body.text,body.message,body.prompt,body.query,body.content].find(x=>typeof x==="string") as string|undefined;
    const text=rawText?.trim();
    if(!text||text.length>4000)throw new BridgeError(400,"INVALID_MESSAGE","语音问题必须为 1–4000 字符");
    const baby=await loadWebBaby(growdeskFetch,session.accessToken,body.babyId);
    if(!baby)throw new BridgeError(404,"BABY_NOT_FOUND","请先创建宝宝资料");
    const clientMessageId=typeof body.clientRequestId==="string"?body.clientRequestId:randomUUID();pathId(clientMessageId);
    const fast=await tryVoiceFastPath({text,baby,userId:session.user.id,accessToken:session.accessToken});
    if(fast){
      const logged=await bffVoiceLogStore.createLog({id:clientMessageId,userId:session.user.id,babyId:baby.id,prompt:text,reply:fast,isAsync:false,isFastPath:true,acknowledged:true,accessToken:session.accessToken});
      return Response.json({success:true,async:false,fastPath:true,reply:fast,logId:logged.id});
    }
    const conversation=requireData(await growdeskFetch<{id:string}>("/api/v1/web/ai/sessions",{
      method:"POST",accessToken:session.accessToken,body:{babyId:baby.id,contextType:"voice",title:text.slice(0,24),clientRequestId:clientMessageId}
    }));
    let run=requireData(await growdeskFetch<DurableChatRun>(`/api/v1/ai/sessions/${pathId(conversation.id)}/runs`,{
      method:"POST",accessToken:session.accessToken,body:{message:text,clientMessageId}
    }));
    const timeout=Math.min(Math.max(typeof body.timeoutMs==="number"?body.timeoutMs:10000,0),12000);
    const deadline=Date.now()+timeout;
    while(!["succeeded","failed","cancelled","awaiting_confirmation"].includes(run.status)&&Date.now()<deadline&&!request.signal.aborted){
      await new Promise(resolve=>setTimeout(resolve,400));
      run=requireData(await growdeskFetch<DurableChatRun>(`/api/v1/ai/runs/${pathId(run.id)}`,{accessToken:session.accessToken}));
    }
    if(run.userId!==session.user.id||run.babyId!==baby.id)throw new BridgeError(502,"RUN_SCOPE_MISMATCH","后端语音任务归属不符");
    if(run.status==="failed"||run.status==="cancelled")throw new BridgeError(502,"VOICE_RUN_FAILED",run.errorMessage||"语音处理失败");
    const needsConfirmation=run.status==="awaiting_confirmation";
    return Response.json({success:true,async:!["succeeded","awaiting_confirmation"].includes(run.status),fastPath:false,sessionId:conversation.id,runId:run.id,needsConfirmation,
      reply:run.resultSummary||(needsConfirmation?"请在网页中核对并确认拟写入的记录。":"任务已保存，稍后可在语音记录和会话中读取。"),plan:run.proposedPlan??null});
  });
}
